ALTER TYPE "FeedReportResolution" ADD VALUE IF NOT EXISTS 'NO_VIOLATION';
ALTER TYPE "FeedReportResolution" ADD VALUE IF NOT EXISTS 'CONTENT_RESTRICTED';
ALTER TYPE "FeedReportResolution" ADD VALUE IF NOT EXISTS 'CONTENT_REMOVED';
BEGIN;
ALTER TABLE provider_profiles ADD COLUMN "feedPostingBlocked" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "feedPostingBlockReason" VARCHAR(500);
ALTER TABLE feed_posts ADD COLUMN "safetyScore" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "safetyLabels" TEXT[] NOT NULL DEFAULT '{}', ADD COLUMN "safetyCheckedAt" TIMESTAMP(3);
ALTER TABLE feed_post_media ADD COLUMN sha256 VARCHAR(64), ADD COLUMN "deliveryType" VARCHAR(20) NOT NULL DEFAULT 'upload';
ALTER TABLE feed_media_cleanup ADD COLUMN "deliveryType" VARCHAR(20) NOT NULL DEFAULT 'upload';
ALTER TABLE feed_comments ADD COLUMN "moderationHidden" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE feed_reports ADD COLUMN "revisionNumber" INTEGER NOT NULL DEFAULT 1, ADD COLUMN "policyCode" VARCHAR(60), ADD COLUMN note VARCHAR(500);
UPDATE feed_reports r SET "revisionNumber"=p."revisionNumber" FROM feed_posts p WHERE p.id=r."postId";
ALTER TABLE feed_moderation_appeals DROP CONSTRAINT feed_moderation_appeals_status_check;
ALTER TABLE feed_moderation_appeals ADD CONSTRAINT feed_moderation_appeals_status_check CHECK(status IN ('PENDING','UPHELD','REVERSED','WITHDRAWN','EXPIRED'));
CREATE TABLE feed_blocked_media (sha256 VARCHAR(64) NOT NULL,"postId" TEXT NOT NULL,"revisionNumber" INTEGER NOT NULL,active BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(sha256,"postId","revisionNumber"));
CREATE TABLE feed_notices (id TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE ON UPDATE CASCADE,"postId" TEXT NOT NULL REFERENCES feed_posts(id) ON DELETE RESTRICT ON UPDATE CASCADE,event VARCHAR(60) NOT NULL,"sourceKey" VARCHAR(200) NOT NULL UNIQUE,detail VARCHAR(1000) NOT NULL,managed BOOLEAN NOT NULL DEFAULT false,"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "feed_notices_userId_createdAt_id_idx" ON feed_notices("userId","createdAt",id);
ALTER TABLE feed_notices ADD COLUMN "transportQueuedAt" TIMESTAMP(3);
CREATE TABLE feed_comment_reports (id TEXT PRIMARY KEY,"commentId" TEXT NOT NULL REFERENCES feed_comments(id) ON DELETE CASCADE ON UPDATE CASCADE,"userId" TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE ON UPDATE CASCADE,reason "FeedReportReason" NOT NULL,detail VARCHAR(500),resolution VARCHAR(30),"reviewedById" TEXT,"reviewedAt" TIMESTAMP(3),note VARCHAR(500),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "feed_comment_reports_commentId_userId_key" ON feed_comment_reports("commentId","userId");
CREATE INDEX "feed_comment_reports_resolution_createdAt_id_idx" ON feed_comment_reports(resolution,"createdAt",id);
COMMIT;
